[Form]
public final class METSalesLineOpenOrder extends FormRun implements SysIFilterConsumerForm,SysIFilterEventHandler, METItemInquiryFilerProvider
{
    QueryBuildRange         headerVoided;
    QueryBuildRange         headerType;
    QueryBuildRange         headerProjId;
    QueryBuildRange         lineVoided;
    InventDimCtrl_Frm_Mov   inventDimFormSetup;
    FormRun                 formRun;
    ItemId                  itemIdFilter;
    InventLocationId        inventLocationIdFilter;

}

/// <summary>
/// Register the data source to which the filter should be applied.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    SalesLine_ds.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

/// <summary>
/// Initialize the filter consumer form.
/// </summary>
void init()
{
    formRun = element.args().caller() as FormRun;

    super();

    QueryBuildDataSource qbdsUserWarehouse;
    qbdsUserWarehouse = InventDim_ds.queryBuildDataSource().addDataSource(tableNum(METAllowedWarehousesForISPUsers));
    qbdsUserWarehouse.joinMode(JoinMode::ExistsJoin);
    qbdsUserWarehouse.addLink(fieldnum(InventDim, InventLocationId), fieldNum(METAllowedWarehousesForISPUsers, InventLocationID));
    qbdsUserWarehouse.addRange(fieldnum(METAllowedWarehousesForISPUsers, UserId)).value(curUserId());
    InventDim_ds.executeQuery();
}

/// <summary>
/// Parameter method to get the ItemId filter from the filter form.
/// </summary>
/// <returns>ItemId</returns>
public ItemId parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(ItemId));

}

/// <summary>
/// Event handler to react on a filter change.
/// </summary>
public void onFilterChanged()
{
    SalesLine_ds.research();
    SalesLine_ds.executeQuery();
}

/// <summary>
/// Parameter method to get the InventLocationId filter from the filter form.
/// </summary>
/// <returns>InventLocationId</returns>
public InventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(InventLocationId));
}

/// <summary>
/// Execute query
/// </summary>
public void executeQuery()
{
    QueryBuildDataSource    qbdsItemBarcode = this.queryBuildDataSource();
    QueryBuildDataSource    inventDimds = InventDim_ds.queryBuildDataSource();

    itemIdFilter            = formRun.parmItemId();

    qbdsItemBarcode.clearRanges();
    inventDimds.clearRanges();

    if (itemIdFilter)
    {
        qbdsItemBarcode.addRange(fieldNum(SalesLine, ItemId)).value(queryValue(itemIdFilter));
        qbdsItemBarcode.addRange(fieldNum(SalesLine, ItemId)).status(RangeStatus::Locked);
    }

    inventLocationIdFilter  = formRun.parminventoryLocationId();

    if (inventLocationIdFilter)
    {
        inventDimds.addRange(fieldNum(InventDim, InventLocationId)).value(queryValue(inventLocationIdFilter));
        inventDimds.addRange(fieldNum(InventDim, InventLocationId)).status(RangeStatus::Locked);
    }

    super();
}
